#!/usr/bin/env bash
set -Eeuo pipefail

SCRIPT_NAME="vercentlabs-crm-v2-rebuild.sh"
RUN_ID="$(date +%Y%m%d-%H%M%S)"
EXPECTED_PATCH_SHA256="8c89a3c4cb3b7b78cdc9670d48bad4a6dc3acf43ffeed859338dc66db6e56f7f"
PATCH_APPLIED=0
REPORT=""
LOG_FILE=""
PATCH_FILE=""
BACKUP_TAG=""
WORK_BRANCH=""
START_HEAD=""
START_BRANCH=""
ROOT=""

say() { printf '%s\n' "$*"; }
section() {
  printf '\n================================================================\n%s\n================================================================\n' "$1"
}
warn() { printf 'WARN: %s\n' "$*" >&2; }
die() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

find_repo_root() {
  local d="$PWD"
  while [[ "$d" != "/" && -n "$d" ]]; do
    if [[ -d "$d/.git" && -f "$d/package.json" && -d "$d/apps/web" && -d "$d/services/api" && -d "$d/database" ]]; then
      printf '%s' "$d"
      return 0
    fi
    d="$(dirname "$d")"
  done
  return 1
}

rollback_on_error() {
  local code=$?
  trap - ERR
  set +e
  if [[ -n "${ROOT:-}" ]]; then cd "$ROOT" 2>/dev/null || true; fi
  if [[ "${PATCH_APPLIED:-0}" == "1" && -n "${PATCH_FILE:-}" && -f "${PATCH_FILE:-}" ]]; then
    warn "A hard CRM v2 validation failed. Reversing only the v2 patch; your pre-existing work is preserved."
    git apply -R --whitespace=nowarn "$PATCH_FILE" >/dev/null 2>&1 || warn "Automatic patch reversal was not clean. Use backup tag ${BACKUP_TAG:-unknown} and the saved backup patches in .crm-rebuild/backups/."
  fi
  if [[ -n "${REPORT:-}" ]]; then
    {
      echo "# CRM v2 rebuild — FAILED"
      echo
      echo "- Run: $RUN_ID"
      echo "- Exit code: $code"
      echo "- Starting HEAD: ${START_HEAD:-unknown}"
      echo "- Starting branch: ${START_BRANCH:-unknown}"
      echo "- Working branch: ${WORK_BRANCH:-unknown}"
      echo "- Backup tag: ${BACKUP_TAG:-unknown}"
      echo "- v2 patch reversed: $([[ ${PATCH_APPLIED:-0} == 1 ]] && echo attempted || echo not-needed)"
      echo
      echo "Inspect the log before retrying: ${LOG_FILE:-unknown}"
    } > "$REPORT" 2>/dev/null || true
  fi
  printf '\nCRM v2 rebuild FAILED safely (exit %s).\n' "$code" >&2
  [[ -n "${LOG_FILE:-}" ]] && printf 'Log: %s\n' "$LOG_FILE" >&2
  [[ -n "${REPORT:-}" ]] && printf 'Report: %s\n' "$REPORT" >&2
  exit "$code"
}
trap rollback_on_error ERR

ROOT="$(find_repo_root)" || die "Run this script from inside the VERCENTLABS ERP repository (repo root is preferred)."
cd "$ROOT"
mkdir -p .crm-rebuild/reports .crm-rebuild/backups .crm-rebuild/tmp
LOG_FILE="$ROOT/.crm-rebuild/reports/v2-run-$RUN_ID.log"
REPORT="$ROOT/.crm-rebuild/reports/v2-run-$RUN_ID.md"
PATCH_FILE="$ROOT/.crm-rebuild/tmp/crm-v2-$RUN_ID.patch"
PAYLOAD_FILE="$ROOT/.crm-rebuild/tmp/crm-v2-$RUN_ID.b64"
exec > >(tee -a "$LOG_FILE") 2>&1

section "1/9 Preflight"
command -v git >/dev/null 2>&1 || die "git is required."
command -v node >/dev/null 2>&1 || die "Node.js is required."
START_HEAD="$(git rev-parse HEAD)"
START_BRANCH="$(git branch --show-current || true)"
[[ -n "$START_BRANCH" ]] || START_BRANCH="DETACHED"
NODE_VERSION="$(node -v)"
NODE_MAJOR="$(node -p 'process.versions.node.split(".")[0]')"
say "Repo: $ROOT"
say "HEAD: $START_HEAD"
say "Branch: $START_BRANCH"
say "Node: $NODE_VERSION"

[[ -f scripts/validation/verify-crm-rebuild.mjs ]] || die "The first CRM hardening pass is not present (missing scripts/validation/verify-crm-rebuild.mjs). Run the previously supplied vercentlabs-crm-rebuild.sh first."
[[ -f apps/web/tests/crm-rebuild-hardening.test.mjs ]] || die "The first CRM hardening pass is not present (missing crm-rebuild-hardening.test.mjs)."

# Idempotent re-run: if the v2 contract validator exists and the hard gates pass, do nothing.
if [[ -f scripts/validation/verify-crm-module-contracts.mjs ]]; then
  say "CRM v2 markers detected; checking whether this rebuild is already applied..."
  if node scripts/validation/verify-crm-rebuild.mjs >/dev/null 2>&1 \
     && node scripts/validation/verify-crm-module-contracts.mjs >/dev/null 2>&1 \
     && node scripts/validation/verify-web-boundaries.mjs >/dev/null 2>&1 \
     && node scripts/validation/verify-architecture.mjs >/dev/null 2>&1 \
     && node apps/web/scripts/verify-routes.mjs >/dev/null 2>&1; then
    say "CRM v2 is already applied and its hard architecture gates pass. Nothing changed."
    exit 0
  fi
fi

if [[ "$NODE_MAJOR" != "24" ]]; then
  warn "Repository engines require Node 24.x; you have $NODE_VERSION. Dependency-free reconstruction and validation will run. Full pnpm verification will be skipped unless Node 24.x is active."
fi

section "2/9 Preserve current state"
BACKUP_TAG="crm-v2-backup-$RUN_ID"
if git rev-parse -q --verify "refs/tags/$BACKUP_TAG" >/dev/null; then
  BACKUP_TAG="crm-v2-backup-$RUN_ID-$RANDOM"
fi
git tag "$BACKUP_TAG" "$START_HEAD"
say "Created local backup tag: $BACKUP_TAG"

git diff --binary > ".crm-rebuild/backups/pre-v2-unstaged-$RUN_ID.patch" || true
git diff --cached --binary > ".crm-rebuild/backups/pre-v2-staged-$RUN_ID.patch" || true
git ls-files --others --exclude-standard > ".crm-rebuild/backups/pre-v2-untracked-$RUN_ID.txt" || true

WORK_BRANCH="crm-v2-rebuild/$RUN_ID"
if git show-ref --verify --quiet "refs/heads/$WORK_BRANCH"; then
  WORK_BRANCH="crm-v2-rebuild/$RUN_ID-$RANDOM"
fi
git switch -c "$WORK_BRANCH"
say "Working branch: $WORK_BRANCH"
say "Your existing first-pass changes remain in the worktree and are not stashed or discarded."

section "3/9 Decode and verify the tested CRM v2 patch"
cat <<'CRM_V2_PAYLOAD' > "$PAYLOAD_FILE"
