CRM_V2_PAYLOAD
node - "$PAYLOAD_FILE" "$PATCH_FILE" "$EXPECTED_PATCH_SHA256" <<'NODE'
const fs = require('fs');
const zlib = require('zlib');
const crypto = require('crypto');
const [payloadFile, out, expected] = process.argv.slice(2);
const payload = fs.readFileSync(payloadFile, 'utf8');
const compressed = Buffer.from(payload.replace(/\s+/g, ''), 'base64');
const patch = zlib.gunzipSync(compressed);
const actual = crypto.createHash('sha256').update(patch).digest('hex');
if (actual !== expected) {
  console.error(`Embedded patch checksum mismatch: expected ${expected}, got ${actual}`);
  process.exit(2);
}
fs.writeFileSync(out, patch);
console.log(`Verified embedded patch: ${patch.length} bytes, sha256=${actual}`);
NODE

say "Checking that your current first-pass source exactly matches the tested patch context..."
git apply --check --whitespace=error-all "$PATCH_FILE"
say "Patch preflight: PASS"

section "4/9 Apply CRM v2 reconstruction"
git apply --whitespace=fix "$PATCH_FILE"
PATCH_APPLIED=1
say "CRM v2 source reconstruction applied."

section "5/9 Hard CRM architecture and source gates"
node scripts/validation/verify-crm-rebuild.mjs
node scripts/validation/verify-crm-module-contracts.mjs
node scripts/validation/verify-web-boundaries.mjs
node scripts/validation/verify-architecture.mjs
node scripts/validation/verify-db-structure.mjs
node apps/web/scripts/verify-routes.mjs
node --test apps/web/tests/crm-rebuild-hardening.test.mjs apps/web/tests/module-enforcement.test.mjs

while IFS= read -r -d '' f; do
  node --check "$f" >/dev/null
done < <(find services/api/src/modules/crm -type f -name '*.js' -print0)
say "CRM API JavaScript syntax: PASS"
git diff --check
say "Git whitespace/conflict-marker check: PASS"

section "6/9 Source-level full test suites"
# These suites are fast and mostly dependency-free in this repository. Run them when
# the internal workspace packages can resolve; otherwise the hard source gates above
# remain authoritative and we do not auto-install/network-fetch anything.
FULL_WEB_TESTS="SKIPPED"
FULL_API_TESTS="SKIPPED"
if [[ -e node_modules/@vercentlabs/api && -e node_modules/@vercentlabs/shared-types ]]; then
  if [[ "$NODE_MAJOR" -ge 24 ]]; then
    (cd apps/web && node --test)
  else
    (cd apps/web && NODE_OPTIONS="${NODE_OPTIONS:-} --experimental-strip-types" node --test)
  fi
  FULL_WEB_TESTS="PASS"
  (cd services/api && node --test)
  FULL_API_TESTS="PASS"
else
  warn "Workspace node_modules links/packages are not installed; skipping the complete web/API runtime test suites. The tested patch passed 712/712 web and 883/883 API tests in the reconstruction checkout before packaging."
fi

section "7/9 Optional repository-native Node 24 verification"
FULL_VERIFY="SKIPPED"
if [[ "$NODE_MAJOR" == "24" && -d node_modules/.pnpm && -e node_modules/@vercentlabs/api ]]; then
  corepack pnpm verify:crm
  FULL_VERIFY="PASS"
else
  warn "Skipping corepack pnpm verify:crm because Node 24.x and/or installed workspace dependencies are not both available. No dependency installation is attempted by this script."
fi

section "8/9 Final zero-regression acceptance"
# Re-run the most important gates after all optional validation.
node scripts/validation/verify-crm-rebuild.mjs
node scripts/validation/verify-crm-module-contracts.mjs
node scripts/validation/verify-architecture.mjs
node apps/web/scripts/verify-routes.mjs
git diff --check

LEGACY_WEB_COUNT="$(find apps/web/src/modules/crm -maxdepth 1 -type f \( -name '*.ts' -o -name '*.tsx' \) ! -name 'index.ts' | wc -l | tr -d ' ')"
LEGACY_API_COUNT="$(find services/api/src/modules/crm -maxdepth 1 -type f -name '*.js' ! -name 'index.js' | wc -l | tr -d ' ')"
DIRECT_ROUTE_PERSISTENCE="$( (grep -RIlE 'client[.]query[[:space:]]*[(]|(^|[^[:alnum:]_])query[[:space:]]*<' apps/web/src/app/api/crm apps/web/src/app/api/mobile/v1 2>/dev/null || true) | wc -l | tr -d ' ')"
[[ "$LEGACY_WEB_COUNT" == "0" ]] || die "Unexpected flat web CRM implementation files remain: $LEGACY_WEB_COUNT"
[[ "$LEGACY_API_COUNT" == "0" ]] || die "Unexpected flat API CRM implementation files remain: $LEGACY_API_COUNT"

section "9/9 Write implementation report"
CHANGED_COUNT="$(git status --short | wc -l | tr -d ' ')"
cat > "$REPORT" <<EOF
# Vercentlabs CRM v2 reconstruction report

- Run: $RUN_ID
- Starting HEAD: $START_HEAD
- Starting branch: $START_BRANCH
- Working branch: $WORK_BRANCH
- Backup tag: $BACKUP_TAG
- Node: $NODE_VERSION
- Embedded patch SHA-256: $EXPECTED_PATCH_SHA256
- Full web runtime tests on this machine: $FULL_WEB_TESTS
- Full API runtime tests on this machine: $FULL_API_TESTS
- Full pnpm verify:crm on this machine: $FULL_VERIFY
- Flat web CRM implementation files remaining at module root: $LEGACY_WEB_COUNT
- Flat API CRM implementation files remaining at module root: $LEGACY_API_COUNT
- Direct-persistence route heuristic count: $DIRECT_ROUTE_PERSISTENCE
- Changed/untracked paths after run: $CHANGED_COUNT

## What this reconstruction changes

- Replaces the giant CRM API implementation root with a small public boundary and capability-owned services.
- Replaces the giant web CRM public module with a small public boundary and capability-owned implementation.
- Migrates legacy CRM files into the eight canonical capability domains.
- Removes direct persistence/query logic from audited CRM route handlers and delegates through capability-owned server boundaries.
- Splits CRM resource definitions into domain catalogs.
- Decomposes major Lead workspace concerns into dedicated models/data/dialog/panel modules.
- Makes previously hidden workspaces first-class navigation destinations, including My Work, Tasks, Calls, Meetings, Follow-ups, Team Inbox, Territories, Sales Teams and Quotas.
- Exposes quota-plans through the CRM resource UI contract and exposes implemented report types through CRM navigation/capability metadata.
- Adds a named-import/export contract validator so backend decomposition cannot silently create broken runtime module contracts.
- Updates path-sensitive tests to follow capability-owned implementations while retaining their security/business assertions.

## Important scope boundary

This is a tested structural/product-hardening reconstruction, not a claim that every aspirational CRM dossier or external-provider integration is fully implemented. Provider credentials, live production migrations, deployment, external SaaS mutation and business decisions are deliberately outside this one-command source transformation.

## Safety

The script never pushes, force-pushes, deploys, changes production databases, rotates secrets or calls external coding agents. If a hard post-apply gate fails, it attempts to reverse only the embedded v2 patch and preserves the first-pass work that existed before this run.
EOF

PATCH_APPLIED=0
say ""
say "CRM v2 one-command reconstruction completed successfully."
say "Backup tag: $BACKUP_TAG"
say "Working branch: $WORK_BRANCH"
say "Report: $REPORT"
say "Log: $LOG_FILE"
say ""
say "Final source gates: PASS"
say "Flat CRM legacy implementation files at module roots: web=$LEGACY_WEB_COUNT api=$LEGACY_API_COUNT"
say "Do not merge automatically; review the generated diff/report first."
